mapper.sql:
WHERE membership.clan_id = #{criteria.clanId}
  AND app_user.deleted_at IS NULL


  AND EXISTS (
    SELECT 1
    FROM member_role visible_role
    WHERE visible_role.membership_id = membership.id
      AND visible_role.status = 'active'
      AND (


            (
              visible_role.scope_type = #{criteria.branchScope}
              AND visible_role.scope_id IN

                #{id}

            )

          false

        OR


            (
              visible_role.scope_type = #{criteria.branchSubtreeScope}
              AND visible_role.scope_id IN

                #{id}

            )

          false

      )
  )





      AND membership.member_status IN

        #{v}



      AND false





  AND (
    lower(app_user.username) LIKE concat('%', #{criteria.keyword}, '%')
    OR lower(app_user.display_name) LIKE concat('%', #{criteria.keyword}, '%')
  )





      AND EXISTS (
        SELECT 1
        FROM member_role mr
        JOIN app_role role ON role.id = mr.role_id
        WHERE mr.membership_id = membership.id
          AND mr.status = 'active'
          AND role.role_code IN

            #{v}

      )


      AND false







      AND EXISTS (
        SELECT 1
        FROM member_role scoped
        WHERE scoped.membership_id = membership.id
          AND scoped.status = 'active'
          AND scoped.scope_type IN

            #{v}

      )


      AND false

mapper.select:
SELECT DISTINCT membership.*
FROM clan_membership membership
JOIN app_user ON app_user.id = membership.user_id

ORDER BY membership.id ASC
LIMIT #{limit}
OFFSET #{offset}
